function validate([n, k]) {
  if (!Number.isInteger(n) || !Number.isInteger(k)) return 'n and k must be whole numbers.';
  if (n < 1 || n > 50) return 'n must be between 1 and 50.';
  if (k < 1 || k > n) return 'k must be between 1 and n.';
  return null;
}

