function circularGameLosers(n, k) {
  const received = new Array(n).fill(false);
  let current = 0;
  let turn = 1;

  while (!received[current]) {
    received[current] = true;
    current = (current + turn * k) % n;
    turn++;
  }

  const losers = [];
  for (let i = 0; i < n; i++) {
    if (!received[i]) {
      losers.push(i + 1);
    }
  }
  return losers;
}

