function circularGameLosers(n, k) {
  // Walk the ball around the circle one seat at a time, using 1-based friend numbers.
  const held = new Set([1]);
  let holder = 1;
  for (let pass = 1; ; pass++) {
    for (let step = 0; step < pass * k; step++) holder = holder === n ? 1 : holder + 1;
    if (held.has(holder)) break;
    held.add(holder);
  }
  const result = [];
  for (let friend = 1; friend <= n; friend++) if (!held.has(friend)) result.push(friend);
  return result;
}

