function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 12) : pick(35, 50);
  const roll = rand();
  let k;
  if (roll < 0.15) k = n;
  else if (roll < 0.3) k = 1;
  else k = pick(1, n);
  return [n, k];
}
